def assign(self, ticket_id: int, assignee: str) -> Ticket:
        ticket = self.get(ticket_id)
        ticket.assignee = assignee
        self.store.save(ticket)
        if self.notifier:
            try:
                self.notifier(assignee, f"Ticket {ticket.id} was assigned to you: {ticket.title}")
            except Exception:
                pass
        return ticket
